public class InnerMessageTemplateContentFactory(Action<Humidifier.Wisdom.MessageTemplateTypes.Content> factoryAction = null) : SubResourceFactory<Humidifier.Wisdom.MessageTemplateTypes.Content>
{

    internal InnerMessageTemplateEmailMessageTemplateContentFactory EmailMessageTemplateContentFactory { get; set; }

    internal InnerMessageTemplateSmsMessageTemplateContentFactory SmsMessageTemplateContentFactory { get; set; }

    protected override Humidifier.Wisdom.MessageTemplateTypes.Content Create()
    {
        var contentResult = CreateContent();
        factoryAction?.Invoke(contentResult);

        return contentResult;
    }

    private Humidifier.Wisdom.MessageTemplateTypes.Content CreateContent()
    {
        var contentResult = new Humidifier.Wisdom.MessageTemplateTypes.Content();

        return contentResult;
    }
    public override void CreateChildren(Humidifier.Wisdom.MessageTemplateTypes.Content result)
    {
        base.CreateChildren(result);

        result.EmailMessageTemplateContent ??= EmailMessageTemplateContentFactory?.Build();
        result.SmsMessageTemplateContent ??= SmsMessageTemplateContentFactory?.Build();
    }

} // End Of Class

